<script setup lang="ts">
import type { PointDraft } from '@/api/tracking'
defineProps<{ modelValue: PointDraft }>(); const emit=defineEmits<{ 'update:modelValue':[PointDraft] }>(); function patch(m:PointDraft,v:Partial<PointDraft>){emit('update:modelValue',{...m,...v})}
</script>
<template><section class="wizard-form"><h2>触发与统计</h2><label>触发页面<input :value="modelValue.trigger_page" @input="patch(modelValue,{trigger_page:($event.target as HTMLInputElement).value})"></label><label>触发时机<textarea :value="modelValue.trigger_timing" @input="patch(modelValue,{trigger_timing:($event.target as HTMLTextAreaElement).value})" /></label><label>触发次数规则<input :value="modelValue.trigger_count_rule" @input="patch(modelValue,{trigger_count_rule:($event.target as HTMLInputElement).value})"></label><div class="inline-fields"><label><input type="checkbox" :checked="modelValue.count_pv" @change="patch(modelValue,{count_pv:($event.target as HTMLInputElement).checked})"> 统计 PV</label><label><input type="checkbox" :checked="modelValue.count_uv" @change="patch(modelValue,{count_uv:($event.target as HTMLInputElement).checked})"> 统计 UV</label></div><label>UV 模式<select :value="modelValue.uv_mode" @change="patch(modelValue,{uv_mode:($event.target as HTMLSelectElement).value as PointDraft['uv_mode']})"><option value="APPROXIMATE">近似 HLL</option><option value="EXACT">精确</option></select></label><label>统计时间<select :value="modelValue.time_basis" @change="patch(modelValue,{time_basis:($event.target as HTMLSelectElement).value as PointDraft['time_basis']})"><option value="CLIENT">客户端事件时间</option><option value="SERVER">服务端接收时间</option></select></label><fieldset><legend>支持平台</legend><label v-for="p in ['web','ios','android','mini_program','server']" :key="p"><input type="checkbox" :checked="modelValue.supported_platforms.includes(p)" @change="patch(modelValue,{supported_platforms:($event.target as HTMLInputElement).checked?[...modelValue.supported_platforms,p]:modelValue.supported_platforms.filter(v=>v!==p)})"> {{ p }}</label></fieldset></section></template>
